import type { CatalogService } from '../core/catalogPort'
import type {
  GetProductResult,
  ListCategoriesResult,
  SearchProductsResult,
} from '../core/catalogTypes'
import type { ComposableExecutor } from './executorAddressService'

/**
 * Catalog methods on the composable-core transport seam (Foundry-30845).
 * The host's runtime factory supplies the executor — this package never
 * talks to a network or to Salesforce directly. The method names live in
 * core (shared with the server-side handler); re-exported here for hosts.
 */
import { CATALOG_EXECUTOR_METHODS } from '../core/catalogPort'
export { CATALOG_EXECUTOR_METHODS }

const errorMessageOf = (error: unknown): string =>
  error instanceof Error ? error.message : 'Catalog service request failed'

/** Wraps an executor as a CatalogService. Executor failures become `{ status: 'error' }` — never a rejection. */
export function createExecutorCatalogService(executor: ComposableExecutor): CatalogService {
  return {
    async searchProducts(context, input) {
      try {
        return (await executor(CATALOG_EXECUTOR_METHODS.searchProducts, { context, ...input })) as SearchProductsResult
      } catch (error) {
        return { status: 'error', errorMessage: errorMessageOf(error), products: [], totalCount: 0 }
      }
    },
    async getProduct(context, input) {
      try {
        return (await executor(CATALOG_EXECUTOR_METHODS.getProduct, { context, ...input })) as GetProductResult
      } catch (error) {
        return { status: 'error', errorMessage: errorMessageOf(error) }
      }
    },
    async listCategories(context) {
      try {
        return (await executor(CATALOG_EXECUTOR_METHODS.listCategories, { context })) as ListCategoriesResult
      } catch (error) {
        return { status: 'error', errorMessage: errorMessageOf(error), categories: [] }
      }
    },
  }
}
